(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w2 = Math.cos(x*0.009-t*0.15)*25 + Math.sin(y*0.011+t*0.18)*20;
  const sx = x + w1 + Math.sin(y*0.008+t*0.12)*w2*0.3;
  const sy = y + Math.cos(x*0.012+t*0.25)*15 + w2*0.3 + Math.cos(x*0.007-t*0.1)*10;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.75],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.65],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.55],
    [400+Math.cos(t*0.38+2)*60, 200+Math.sin(t*0.72+4)*45, 0.05, 2.8, 0.85]
  ];
  let aS=0, iS=0, a2=0, i2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w2f = f*(1+Math.sin(d*0.02-t*0.5)*0.3);
    aS += Math.sin(d*w2f - t*sp)*w;
    iS += Math.sin(d*w2f*0.7 + t*sp*0.6 + 1.5)*w;
    a2 += Math.sin(d*w2f*1.4 - t*sp*0.8 + 2.0)*w*0.5;
    i2 += Math.cos(d*w2f*0.5 + t*sp*1.2 - 1.0)*w*0.4;
  }
  const tw = 3.4;
  const act=(aS+a2)/tw, inh=(iS+i2)/tw;
  const n1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const n2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const n3 = Math.sin(sx*0.07+sy*0.06-t*1.5);
  const n4 = Math.sin((sx+sy)*0.12+t*2.5)*0.2;
  const n5 = Math.sin((sx-sy)*0.1-t*2)*0.2;
  const n6 = Math.sin(sx*0.09-t*0.7)*Math.cos(sy*0.08+t*0.9)*0.15;
  const bg = (n1+n2)/2 + n3*0.3 + n4 + n5 + n6;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.9)*0.3;
  const sp4 = Math.cos(dist*0.03+ang*5-t*2.0)*0.25;
  const spiral = (sp1+sp2)*0.4 + sp3 + sp4;
  const pulse = Math.sin(dist*0.02-t*0.8)*0.5+0.5;
  const flow = Math.sin(sx*0.02+t*0.4)*Math.cos(sy*0.025-t*0.3)*0.4;
  const voronoi = (() => {
    let md = 999, sd = 999;
    for (let i = 0; i < 6; i++) {
      const vx = 80+i*70+Math.sin(t*0.3+i*1.8)*30;
      const vy = 40+Math.cos(t*0.25+i*2.1)*25+(i%2)*120;
      const d = Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if (d < md) { sd = md; md = d; } else if (d < sd) { sd = d; }
    }
    return (sd-md)*0.15;
  })();
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const macro = Math.sin(sx*0.008+t*0.15)*Math.cos(sy*0.006-t*0.12)*0.2;
  const raw = act - inh*0.7 + bg*0.3 + spiral + pulse*0.15 + flow + voronoi + cell*0.5 + macro;
  const reaction = Math.tanh(raw*2.0);
  const glow = Math.exp(-Math.abs(reaction)*1.5)*0.4;
  const edge = 1-Math.exp(-Math.abs(reaction)*8)*0.3;
  const blend = reaction*0.7 + cell*0.15 + glow*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,82],[18,85,105],[25,135,125],
    [160,170,80],[210,185,60],[230,140,75],[200,90,70],
    [160,50,75],[100,25,65],[50,15,55],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.3;
  const e = Math.abs(reaction)>0.65?1.12:1.0;
  const bri = lum*e*edge;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*bri)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*bri)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*bri)|0
  ];
}
